PRAGMA foreign_keys=ON;
CREATE TABLE event (id INTEGER PRIMARY KEY CHECK(id=1),title TEXT NOT NULL,starts_at TEXT NOT NULL,timezone TEXT NOT NULL);
INSERT INTO event VALUES(1,'Synthetic legacy event','2026-12-03T18:00:00+09:00','Asia/Seoul');
CREATE TABLE activities (id TEXT PRIMARY KEY CHECK(id IN ('price','blind','byob')),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','open','closed')),published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)),started_at TEXT,actual INTEGER);
INSERT INTO activities(id,title) VALUES('price','블라인드 1 · 가격 맞추기'),('blind','블라인드 2 · 와인 맞추기'),('byob','BYOB · 와인 인기투표');
CREATE TABLE participants (id TEXT PRIMARY KEY,name TEXT NOT NULL,name_key TEXT NOT NULL UNIQUE);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,role TEXT NOT NULL CHECK(role IN ('admin','participant')),participant_id TEXT REFERENCES participants(id),expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,attempts INTEGER NOT NULL);
CREATE TABLE candidates (id TEXT PRIMARY KEY,number INTEGER NOT NULL,name TEXT NOT NULL,object_key TEXT NOT NULL,content_type TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE);
CREATE TABLE answers (activity_id TEXT NOT NULL REFERENCES activities(id),participant_id TEXT NOT NULL REFERENCES participants(id),payload TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(activity_id,participant_id));
CREATE TABLE grades (participant_id TEXT PRIMARY KEY REFERENCES participants(id),result TEXT NOT NULL,private_note TEXT NOT NULL,answer_payload TEXT NOT NULL);
CREATE TRIGGER price_lock BEFORE UPDATE OF actual ON activities WHEN OLD.id='price' AND OLD.started_at IS NOT NULL AND NEW.actual IS NOT OLD.actual BEGIN SELECT RAISE(ABORT,'price_locked'); END;
CREATE TRIGGER candidates_insert_lock BEFORE INSERT ON candidates WHEN EXISTS(SELECT 1 FROM activities WHERE id='byob' AND started_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'candidates_locked'); END;
CREATE TRIGGER candidates_update_lock BEFORE UPDATE ON candidates WHEN EXISTS(SELECT 1 FROM activities WHERE id='byob' AND started_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'candidates_locked'); END;
CREATE TRIGGER candidates_delete_lock BEFORE DELETE ON candidates WHEN EXISTS(SELECT 1 FROM activities WHERE id='byob' AND started_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'candidates_locked'); END;
CREATE TRIGGER answer_insert_open BEFORE INSERT ON answers WHEN NOT EXISTS(SELECT 1 FROM activities WHERE id=NEW.activity_id AND status='open' AND published=0) BEGIN SELECT RAISE(ABORT,'activity_closed'); END;
CREATE TRIGGER answer_update_open BEFORE UPDATE ON answers WHEN NOT EXISTS(SELECT 1 FROM activities WHERE id=NEW.activity_id AND status='open' AND published=0) BEGIN SELECT RAISE(ABORT,'activity_closed'); END;
CREATE TRIGGER blind_grade_invalidate AFTER UPDATE OF payload ON answers WHEN NEW.activity_id='blind' AND OLD.payload<>NEW.payload BEGIN DELETE FROM grades WHERE participant_id=NEW.participant_id; END;
